// One-off import: every eD system a.s. (edshop.edsystem.cz) CPU whose socket matches a
// motherboard already in the catalog from scripts/import-edsystem-motherboards.mjs (AM5,
// LGA1700, LGA1851 — the sockets actually present among those 472 boards; AM4/TR5/TRX5/WRX8
// CPUs are skipped since there are no matching sockets to pair them with, and no LGA4677/Xeon W
// CPUs exist in eD's own "Procesory" category to pair with the single W790 board).
//
// Unlike the motherboard listing, eD's CPU cards already carry a real per-SKU spec line inline
// (Socket/core count/clocks/TDP **and a real PassMark score**, e.g. "Výkon CPU dle
// PassMark:26969") — no separate spec page visit needed, and no price guessing needed for tier:
// tier is derived from that real score using the same thresholds passmark.ts already uses for
// CPUs. Price still has no public source (same B2B login wall as the motherboards) so it's
// estimated per tier, same reasoning as the motherboard import.
//
// Images follow the same convention as scripts/import-edsystem-motherboards.mjs: the bare
// "_0a.jpg" master image downloaded and re-hosted in the component-images Supabase Storage
// bucket, not hotlinked.
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);
const BUCKET = 'component-images';
const EDSYSTEM = 'https://edshop.edsystem.cz';

