function isRealProduct(item) {
  return /\/product-\d+$/.test(item.h) && !/^BAZAR/i.test(item.n.trim());
}

function socketFor(specText) {
  if (/Socket AM5/i.test(specText)) return 'AM5';
  if (/Socket\s*1700\b/i.test(specText)) return 'LGA1700';
  if (/Socket\s*1851\b/i.test(specText)) return 'LGA1851';
  return null; // AM4, TR5, TRX5, sWRX8/WRX8 — no matching motherboard socket in the catalog
}

function numFrom(specText, label) {
  const m = specText.match(new RegExp(label.replace(/[()]/g, '\\$&') + ':\\s*([\\d.]+)'));
  return m ? Number(m[1]) : null;
}

// eD's own "Model procesoru" field (when present) is already a clean canonical name ("AMD Ryzen
// 5 7600", "Intel Core i9-14900K") — far more reliable than trying to strip the marketing title
// ("CPU AMD RYZEN 5 7600, 6-core, 3.8GHz, 38MB cache, 65W, socket AM5, BOX") ourselves. Only
// falls back to title-parsing for the handful of rows missing that field.
function cleanName(rawTitle, specText) {
  const modelMatch = specText.match(/Model procesoru:([^;]+)/);
  if (modelMatch) return modelMatch[1].trim();
  return rawTitle.replace(/^CPU\s+/i, '').split(',')[0].trim();
}

// Same thresholds passmark.ts's tierFromPassmark(isGpu=false, ...) uses — kept in sync by eye
// since this is a standalone Node script that can't import that Next.js module directly.
function tierFromScore(score) {
  if (score >= 63000) return 'S';
  if (score >= 55000) return 'A';
  if (score >= 45000) return 'B';
  if (score >= 30000) return 'C';
  return 'D';
}
const TIER_PRICE = { S: 550, A: 400, B: 280, C: 180, D: 110 };

function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
}

async function uploadImage(imgPath, name) {
  const bareImage = imgPath.replace(/_0a_\d+(\.jpg)$/i, '_0a$1');
  const res = await fetch(EDSYSTEM + bareImage);
  const bytes = res.ok ? Buffer.from(await res.arrayBuffer()) : null;
  if (!bytes) {
    const fallback = await fetch(EDSYSTEM + imgPath);
    if (!fallback.ok) return null;
    return uploadBytes(Buffer.from(await fallback.arrayBuffer()), name);
  }
  return uploadBytes(bytes, name);
}

async function uploadBytes(bytes, name) {
  const path = `${slugify(name)}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.jpg`;
  const { error } = await supabase.storage.from(BUCKET).upload(path, bytes, {
    contentType: 'image/jpeg',
    upsert: false,
  });
  if (error) {
    console.error(`Upload failed for ${name}: ${error.message}`);
    return null;
  }
  const { data } = supabase.storage.from(BUCKET).getPublicUrl(path);
  return data.publicUrl;
}

const apply = process.argv.includes('--apply');

const { data: existingRows, error: existingError } = await supabase.from('components').select('name').eq('category', 'cpu');
if (existingError) throw new Error(`Failed to read existing cpu rows: ${existingError.message}`);
const existingNames = new Set(existingRows.map((r) => r.name.trim().toLowerCase()));

const parsed = [];
const skippedNoSocketMatch = [];
const seenNames = new Set();
for (const item of RAW_ITEMS.filter(isRealProduct)) {
  const socket = socketFor(item.s);
  if (!socket) {
    skippedNoSocketMatch.push(item.n);
    continue;
  }
  const name = cleanName(item.n, item.s);
  const nameKey = name.toLowerCase();
  if (seenNames.has(nameKey) || existingNames.has(nameKey)) continue;
  seenNames.add(nameKey);

  const cores = numFrom(item.s, 'Počet jader');
  const maxFreq = numFrom(item.s, 'Maximální frekvence procesoru (GHz)');
  const baseFreq = numFrom(item.s, 'Frekvence procesoru (GHz)');
  const tdp = numFrom(item.s, 'TDP');
  const passmark = numFrom(item.s, 'Výkon CPU dle PassMark');
  const hasHT = /HyperThreading/i.test(item.s);
  const threads = cores != null ? (hasHT ? cores * 2 : cores) : null;
  const tier = passmark != null ? tierFromScore(passmark) : 'C';

  const specParts = [];
  if (cores != null && threads != null) specParts.push(`${cores}C/${threads}T`);
  if (maxFreq != null) specParts.push(`${maxFreq}GHz`);
  else if (baseFreq != null) specParts.push(`${baseFreq}GHz`);
  if (tdp != null) specParts.push(`${tdp}W`);

  parsed.push({
    name,
    imgPath: item.i,
    socket,
    passmark,
    tier,
    price: TIER_PRICE[tier],
    specs: specParts.join(' · ') || `${socket} CPU`,
  });
}

console.log(`Parsed ${parsed.length} new CPUs (${skippedNoSocketMatch.length} skipped — no matching motherboard socket, ${RAW_ITEMS.length - parsed.length - skippedNoSocketMatch.length} skipped as duplicate/BAZAR/non-product).`);
if (skippedNoSocketMatch.length) {
  console.log('Skipped (no matching socket):', JSON.stringify(skippedNoSocketMatch, null, 2));
}
console.log('Sample:', JSON.stringify(parsed.slice(0, 5), null, 2));

if (!apply) {
  console.log('\n(dry run — pass --apply to actually download images, upload them, and insert rows)');
  process.exit(0);
}

let inserted = 0;
for (const p of parsed) {
  const imageUrl = p.imgPath ? await uploadImage(p.imgPath, p.name) : null;
  const row = {
    category: 'cpu',
    name: p.name,
    price: p.price,
    specs: p.specs,
    tier: p.tier,
    socket: p.socket,
    passmark: p.passmark,
    image_url: imageUrl,
    sort_order: 100,
  };
  const { error } = await supabase.from('components').insert(row);
  if (error) {
    console.error(`INSERT FAILED for ${p.name}: ${error.message}`);
    continue;
  }
  inserted++;
  if (inserted % 25 === 0) console.log(`Inserted ${inserted}/${parsed.length}...`);
}
console.log(`\nDone — inserted ${inserted}/${parsed.length} CPUs.`);
